input.newString:
import { getPosts } from '../lib/api';

export const revalidate = 3600; // 1 hour cache duration
export const dynamic = 'force-static';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <div>
        {posts.map((post) => (
          <article key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </article>
        ))}
      </div>
    </main>
  );
}

